function useAllListingsAdmin(status) {
  return useQuery({
    queryKey: ["admin", "listings", status ?? "all"],
    staleTime: 30 * 1e3,
    gcTime: 5 * 60 * 1e3,
    refetchOnWindowFocus: false,
    refetchOnMount: false,
    queryFn: async () => {
      console.log(`📡 [useAllListingsAdmin] Fetching listings with status: ${status || "all"}`);
      let q = supabase.from("listings").select("*, categories:categories!category_id(slug, name_ar, name_en), governorates:governorates!governorate_id(slug, name_ar, name_en)").order("created_at", { ascending: false });
      if (status) q = q.eq("status", status);
      const { data, error } = await q;
      if (error) {
        console.error("❌ [useAllListingsAdmin] Error:", error);
        throw error;
      }
      if (!data || data.length === 0) {
        console.log("ℹ️ [useAllListingsAdmin] No data found");
        return [];
      }
      const ownerIds = data.map((item) => item.owner_id);
      const { data: profiles } = await supabase.from("profiles").select("id, full_name, store_name").in("id", ownerIds);
      const profileMap = new Map((profiles ?? []).map((p) => [p.id, p]));
      const result = data.map((item) => ({
        ...item,
        profile: profileMap.get(item.owner_id) || null
      }));
      console.log(`✅ [useAllListingsAdmin] Found ${result.length} listings`);
      return result;
    }
  });
}
