function useUserNotifications(userId, options) {
  return useQuery({
    queryKey: ["notifications", "v2", userId, options],
    enabled: !!userId,
    queryFn: async () => {
      let q = supabase.from("notifications").select("*").eq("user_id", userId).order("created_at", { ascending: false });
      if (options?.unreadOnly) {
        q = q.eq("is_read", false);
      }
      if (options?.types && options.types.length > 0) {
        q = q.in("type", options.types);
      }
      if (options?.limit) {
        q = q.limit(options.limit);
      }
      if (options?.offset) {
        q = q.range(options.offset, options.offset + (options.limit || 20) - 1);
      }
      const { data, error } = await q;
      if (error) throw error;
      return data;
    }
  });
}
function useSendNotificationV2() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (params) => {
      const config = NOTIFICATION_CONFIG[params.type];
      const notification = {
        user_id: params.userId,
        type: params.type,
        title_ar: params.titleAr,
        title_en: params.titleEn || params.titleAr,
        body_ar: params.bodyAr,
        body_en: params.bodyEn || params.bodyAr,
        icon: config.icon,
        color: config.color,
        priority: params.priority || config.priority,
        link_url: params.linkUrl || null,
        image_url: params.imageUrl || null,
        actions: params.actions || [],
        metadata: params.metadata || {},
        scheduled_for: params.scheduledFor || null,
        expires_at: params.expiresAt || null,
        is_sent: !params.scheduledFor,
        sent_at: params.scheduledFor ? null : (/* @__PURE__ */ new Date()).toISOString()
      };
      const { data, error } = await supabase.from("notifications").insert(notification).select().single();
      if (error) throw error;
      try {
        if ("serviceWorker" in navigator) {
          const registration = await navigator.serviceWorker.ready;
          await registration.showNotification(
            params.titleAr,
            {
              body: params.bodyAr,
              icon: params.imageUrl || "/logo-192.png",
              badge: "/badge.png",
              color: "#2a655f",
              image: params.imageUrl || null,
              data: {
                url: params.linkUrl || "/dashboard",
                notificationId: data.id
              },
              actions: [
                { action: "view", title: "👀 عرض" },
                { action: "dismiss", title: "✖ إغلاق" }
              ],
              tag: `notification-${data.id}`,
              requireInteraction: true,
              vibrate: [200, 100, 200, 100, 200],
              dir: "rtl",
              lang: "ar",
              timestamp: Date.now()
            }
          );
          console.log("✅ Push notification sent via Service Worker");
        }
      } catch (pushError) {
        console.error("❌ Error sending push notification:", pushError);
      }
      return data;
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["notifications", "v2", data.user_id] });
      queryClient.invalidateQueries({ queryKey: ["notifications", "unread", data.user_id] });
      queryClient.invalidateQueries({ queryKey: ["admin-notifications"] });
    }
  });
}
function useSendBulkNotificationsV2() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (params) => {
      const config = NOTIFICATION_CONFIG[params.type];
      const notifications = params.userIds.map((userId) => ({
        user_id: userId,
        type: params.type,
        title_ar: params.titleAr,
        title_en: params.titleEn || params.titleAr,
        body_ar: params.bodyAr,
        body_en: params.bodyEn || params.bodyAr,
        icon: config.icon,
        color: config.color,
        priority: config.priority,
        link_url: params.linkUrl || null,
        image_url: params.imageUrl || null,
        actions: params.actions || [],
        metadata: params.metadata || {},
        scheduled_for: params.scheduledFor || null,
        expires_at: params.expiresAt || null,
        is_sent: !params.scheduledFor,
        sent_at: params.scheduledFor ? null : (/* @__PURE__ */ new Date()).toISOString()
      }));
      const { data, error } = await supabase.from("notifications").insert(notifications).select();
      if (error) throw error;
      try {
        if (Notification.permission === "granted") {
          new Notification(params.titleAr, {
            body: params.bodyAr,
            icon: params.imageUrl || "/images/logo-192.png",
            badge: "/images/badge.png",
            requireInteraction: true,
            vibrate: [200, 100, 200, 100, 200],
            dir: "rtl",
            lang: "ar",
            data: {
              url: params.linkUrl || "/dashboard"
            }
          });
          console.log("✅ Push notification sent successfully!");
        } else {
          console.log("❌ Notification permission not granted");
        }
      } catch (pushError) {
        console.error("❌ Error sending push notification:", pushError);
      }
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["notifications", "v2"] });
      queryClient.invalidateQueries({ queryKey: ["admin-notifications"] });
    }
  });
}
