function useCart(userId) {
  return useQuery({
    queryKey: ["cart", userId],
    enabled: !!userId,
    queryFn: async () => {
      if (!userId) return null;
      console.log("🔄 [useCart] Fetching cart for user:", userId);
      const { data: cart, error } = await supabase.from("carts").select(`
          *,
          store:store_id (
            id,
            store_name,
            store_logo_url
          )
        `).eq("user_id", userId).eq("status", "active").order("total_items", { ascending: false }).limit(1).maybeSingle();
      if (error) {
        console.error("❌ [useCart] Error fetching cart:", error);
        throw error;
      }
      if (!cart) {
        console.log("📭 [useCart] No active cart found");
        return null;
      }
      const { data: items, error: itemsError } = await supabase.from("cart_items").select(`
          *,
          listings:listing_id (
            id,
            title_ar,
            title_en,
            description_ar,
            description_en,
            cover_url,
            owner_id,
            price,
            price_usd,
            old_price,
            currency,
            is_offer,
            discount_percent,
            is_available,
            is_featured,
            rating,
            views,
            favorites_count,
            kind,
            status,
            delivery_method,
            delivery_note,
            payment_method,
            metadata,
            governorate_id,
            category_id,
            created_at,
            updated_at,
            profile:profiles!owner_id (
              id,
              full_name,
              phone,
              avatar_url,
              bio,
              store_name,
              store_logo_url,
              store_cover_url,
              allows_messaging,
              allows_bookings,
              store_online,
              store_opens_at,
              store_closes_at
            ),
            governorates:governorate_id (
              id,
              name_ar,
              name_en,
              slug
            ),
            categories:category_id (
              id,
              name_ar,
              name_en,
              slug,
              icon,
              image_url
            ),
            colors:product_colors (
              id,
              color_name_ar,
              color_name_en,
              color_hex,
              image_url,
              sort_order
            ),
            variations:product_variations (
              id,
              sku,
              combination,
              price,
              old_price,
              stock_quantity,
              reserved_quantity,
              image_url,
              is_active,
              color_id,
              created_at,
              updated_at
            ),
            options:product_options (
              id,
              option_type,
              option_value,
              option_label_ar,
              option_label_en,
              sort_order
            ),
            listing_images (
              id,
              url,
              sort_order
            )
          )
        `).eq("cart_id", cart.id).order("created_at", { ascending: true });
      if (itemsError) {
        console.error("❌ [useCart] Error fetching items:", itemsError);
        throw itemsError;
      }
      console.log(`✅ [useCart] Cart loaded: ${items?.length || 0} items`);
      const itemsWithSubtotal = items?.map((item) => {
        const listing = item.listings || item.listing || null;
        if (listing?.variations && listing.variations.length > 0) {
          console.log(`🔍 [useCart] Listing ${listing.id} has ${listing.variations.length} variations`);
          console.log(`🔍 [useCart] First variation:`, listing.variations[0]);
        }
        return {
          ...item,
          subtotal: Number(item.price) * item.quantity,
          subtotal_usd: item.price_usd ? Number(item.price_usd) * item.quantity : null,
          listings: listing
          // ✅ تأكد من إرجاع listings مع البيانات الكاملة
        };
      }) || [];
      return {
        ...cart,
        items: itemsWithSubtotal
      };
    },
    staleTime: 1e3 * 60 * 5,
    gcTime: 1e3 * 60 * 10,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
    refetchOnMount: true,
    retry: 2,
    retryDelay: 1e3
  });
}
function useCheckCartCompatibility() {
  return useMutation({
    mutationFn: async ({
      userId,
      listingId,
      newOwnerId
    }) => {
      const { data: cart, error } = await supabase.from("carts").select("id, status").eq("user_id", userId).eq("status", "active").maybeSingle();
      if (error) throw error;
      if (!cart) {
        return { compatible: true, cartId: null, hasItems: false };
      }
      const { data: existingItems, error: itemsError } = await supabase.from("cart_items").select(`
          id,
          listings:listing_id (
            owner_id
          )
        `).eq("cart_id", cart.id).limit(1);
      if (itemsError) throw itemsError;
      if (!existingItems || existingItems.length === 0) {
        return { compatible: true, cartId: cart.id, hasItems: false };
      }
      const currentStoreId = existingItems[0]?.listings?.owner_id;
      if (currentStoreId && currentStoreId !== newOwnerId) {
        return {
          compatible: false,
          cartId: cart.id,
          currentStoreId,
          newStoreId: newOwnerId,
          hasItems: true
        };
      }
      return { compatible: true, cartId: cart.id, hasItems: true };
    }
  });
}
