function useClearCart() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async ({ userId }) => {
      console.log("🔄 [useClearCart] Clearing cart for user:", userId);
      const { data: cart, error } = await supabase.from("carts").select("id").eq("user_id", userId).eq("status", "active").maybeSingle();
      if (error) throw error;
      if (!cart) {
        console.log("📭 [useClearCart] No active cart found");
        return;
      }
      const { error: deleteError } = await supabase.from("cart_items").delete().eq("cart_id", cart.id);
      if (deleteError) throw deleteError;
      await supabase.from("carts").update({
        store_id: null,
        total_items: 0,
        total_price: 0,
        total_price_usd: 0
      }).eq("id", cart.id);
      console.log("✅ [useClearCart] Cart cleared");
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["cart", variables.userId] });
      toast$1.success("🧹 تم تفريغ السلة");
    },
    onError: (error) => {
      console.error("❌ [useClearCart] Error:", error);
      toast$1.error("❌ فشل تفريغ السلة");
    }
  });
}
async function updateCartTotals(cartId) {
  try {
    console.log("🔄 [updateCartTotals] Updating totals for cart:", cartId);
    const { data: items, error } = await supabase.from("cart_items").select("quantity, price, price_usd").eq("cart_id", cartId);
    if (error) throw error;
    const totalItems = items.reduce((sum, item) => sum + item.quantity, 0);
    const totalPrice = items.reduce((sum, item) => sum + Number(item.price) * item.quantity, 0);
    const totalPriceUsd = items.reduce((sum, item) => sum + (Number(item.price_usd) || 0) * item.quantity, 0);
    const { error: updateError } = await supabase.from("carts").update({
      total_items: totalItems,
      total_price: totalPrice,
      total_price_usd: totalPriceUsd,
      updated_at: (/* @__PURE__ */ new Date()).toISOString()
    }).eq("id", cartId);
    if (updateError) throw updateError;
    console.log(`✅ [updateCartTotals] Totals updated: ${totalItems} items, ${totalPrice} total`);
  } catch (error) {
    console.error("❌ [updateCartTotals] Error:", error);
  }
}
